function topWord(words) {
  let best = null, bestCount = 0;
  for (const w of words) {
    let count = 0;
    for (const other of words) {      // O(n) inner scan per word → O(n²)
      if (other === w) count++;
    }
    if (count > bestCount) { bestCount = count; best = w; }
  }
  return best;
}

console.log(topWord(["a", "b", "a", "c", "b", "a"]));  // expect: a

